using System.Globalization;
using System.Text.Json;
using Microsoft.VisualBasic.FileIO;
using DessertKitchen.Domain;
namespace DessertKitchen.Infrastructure;
public sealed partial class Store {
 public List<string[]> ParseSalesCsv(string text){Guard.Require(text.Length>0&&text.Length<=1000000,"Upload a CSV up to 1 MB.");using var parser=new TextFieldParser(new StringReader(text.TrimStart('\uFEFF'))){TextFieldType=FieldType.Delimited,HasFieldsEnclosedInQuotes=true,TrimWhiteSpace=true};parser.SetDelimiters(",");var rows=new List<string[]>();try{while(!parser.EndOfData){var row=parser.ReadFields()!;Guard.Require(row.Length<=100&&rows.Count<=1000,"Use up to 100 columns and 1,000 order rows.");rows.Add(row);}}catch(MalformedLineException){throw new ValidationException("Malformed CSV quoting. Check the file before importing.");}Guard.Require(rows.Count>=2&&rows[0].Distinct(StringComparer.OrdinalIgnoreCase).Count()==rows[0].Length,"CSV needs unique column headings and at least one data row.");return rows;}
 public List<ImportRow> PreviewSalesImport(SalesImportInput input){
  var rows=ParseSalesCsv(input.Csv);var header=rows[0];foreach(var key in new[]{"reference","date","gross"})Guard.Require(input.Columns.TryGetValue(key,out var col)&&header.Contains(col),"Map "+key+" before previewing.");
  var existing=Orders();var seen=new HashSet<string>();var result=new List<ImportRow>();var channel=CurrentBusiness().Channels.SingleOrDefault(c=>c.Id==input.ChannelId)??throw new ValidationException("Select a channel.");
  for(int index=1;index<rows.Count;index++){string reference="";try{
   var row=rows[index];Guard.Require(row.Length==header.Length,"Column count does not match the heading row.");
   string Cell(string key)=>input.Columns.TryGetValue(key,out var col)&&Array.IndexOf(header,col)>=0?row[Array.IndexOf(header,col)].Trim():"";
   decimal? Optional(string key){var s=Cell(key);if(s.Length==0)return null;Guard.Require(decimal.TryParse(s,NumberStyles.AllowDecimalPoint|NumberStyles.AllowLeadingSign,CultureInfo.InvariantCulture,out var amount),"Use plain decimal numbers for "+key+" (no currency symbols or thousands separators).");Guard.Require(Math.Abs(amount)<=1000000,"Amount is too large.");return amount;}
   reference=Cell("reference");Guard.Text(reference,"Platform order reference",150);Guard.Require(seen.Add(reference),"Reference repeated within this file; consolidate it into one order row first.");
   Guard.Require(DateTimeOffset.TryParse(Cell("date"),CultureInfo.InvariantCulture,DateTimeStyles.AssumeUniversal,out var date)&&Cell("date").Length>=10&&Cell("date")[4]=='-'&&date<=DateTimeOffset.UtcNow,"Use an ISO date/time, not a future date. Include a time-zone offset when available.");
   var gross=Optional("gross")??throw new ValidationException("Gross sales required.");var discount=Optional("discount")??0;var refund=Optional("refund")??0;var other=Optional("otherFees")??0;var fees=Optional("commission");var adjustment=Optional("adjustment")??0;var quantity=Optional("quantity")??0;var salesVat=Optional("salesVat");
   Guard.Require(gross>=0&&discount>=0&&discount<=gross&&refund>=0&&refund<=gross-discount&&other>=0&&(fees==null||fees>=0)&&quantity>=0&&quantity==decimal.Truncate(quantity)&&(salesVat==null||salesVat>=0&&salesVat<=gross-discount),"Check quantities, discounts, refunds and fees.");
   var product=Cell("product");var recipe=All<Recipe>("recipe").FirstOrDefault(r=>r.Id==product||r.Name.Equals(product,StringComparison.OrdinalIgnoreCase));var day=DateOnly.FromDateTime(TimeZoneInfo.ConvertTimeBySystemTimeZoneId(date,"GMT Standard Time").Date);RecipeVersion? v=null;if(recipe!=null){try{v=PublishedAt(recipe.Id,day);}catch(ValidationException){}}
   decimal? cost=v==null||quantity==0?null:(v.Cost.IngredientCost+v.Cost.PackagingCost+v.Cost.LabourCost)/v.Recipe.Yield*quantity;
   var source="csv:"+SalesHash(input.Columns.OrderBy(p=>p.Key).ToDictionary(p=>p.Key,p=>Cell(p.Key)));var id="import-"+SalesHash(new{input.ChannelId,reference})[..24];
   var o=new SaleOrder(id,"I-"+id[^8..],1,date.ToString("O"),channel.Id,channel.Name,reference,"completed","awaiting-settlement","",[new(v?.Recipe.Id??"",v?.Recipe.Revision??0,string.IsNullOrEmpty(product)?"Unmapped reported sale":product,quantity,quantity==0?0:gross/quantity,gross,discount,salesVat,cost,CostStatus:"unknown")],gross,discount,gross-discount,salesVat,null,0,0,0,"Historical financial-only import; unmapped tax and quantity information is unknown.",true,refund,adjustment,fees,other,Optional("net"),source);
   var old=existing.FirstOrDefault(o=>o.ChannelId==input.ChannelId&&o.Reference==reference);var status=old==null?"new":old.Source==source?"duplicate":"conflict";
   result.Add(new(index+1,reference,status,status=="conflict"?"Existing order differs. Review its details and reconcile separately; it will not be overwritten.":v==null?"Product costing unavailable. Original source values retained; no stock will move.":"Financial only; no stock will move.",o));
  }catch(ValidationException e){result.Add(new(index+1,reference,"incomplete",e.Message,null));}}
  return result;
 }
 public List<ImportRow> ConfirmSalesImport(SalesImportInput input)=>SalesCommand(input.OperationId,"import",input,(db,tx)=>{
  Guard.Require(input.Confirm,"Preview the file before confirming.");var preview=PreviewSalesImport(input);foreach(var row in preview.Where(r=>r.Status=="new")){WriteOrder(db,tx,row.Order!);Execute(db,tx,"INSERT INTO sales_events VALUES($id,$o,$at,$h,$b,$r)",("$id",input.OperationId+":"+row.Row),("$o",row.Order!.Id),("$at",Now()),("$h",SalesHash(row)),("$b",JsonSerializer.Serialize(new{action="historical-import",importId=input.OperationId,row=row.Row},Json)),("$r",JsonSerializer.Serialize(row.Order,Json)));}
  Execute(db,tx,"INSERT INTO sales_imports VALUES($id,$b)",("$id",input.OperationId),("$b",JsonSerializer.Serialize(input,Json)));return preview;
 });
 public CsvMap SaveSalesMapping(CsvMap input){Guard.Text(input.Id,"Mapping ID",100);Guard.Text(input.Name,"Mapping name",150);Guard.Require(input.Columns.Count<=30,"Too many mapping fields.");using var db=Open();using var tx=db.BeginTransaction();Execute(db,tx,"INSERT INTO documents VALUES('sales-mapping',$id,1,$b) ON CONFLICT(kind,id) DO UPDATE SET body=$b,revision=revision+1",("$id",input.Id),("$b",JsonSerializer.Serialize(input,Json)));Audit(db,tx,"sales:mapping",input.Id);tx.Commit();return input;}
 public List<PayoutRecord> Payouts(){using var db=Open();return InventoryRows<PayoutRecord>(db,null,"sales_payouts");}
 static string PayoutGroup(PayoutInput p)=>p.ChannelId+":"+string.Join(",",p.OrderIds.Order());
 decimal? CurrentPayoutExpected(PayoutRecord p){if(p.OrderSnapshots==null)return p.Expected;var current=Orders();return p.Expected+p.OrderSnapshots.Sum(old=>{var now=current.Single(o=>o.Id==old.Id);return (now.Total-now.Refunds+now.Adjustments-now.OtherFees)-(old.Total-old.Refunds+old.Adjustments-old.OtherFees);});}
 public object PayoutView(){var all=Payouts();var active=all.Where(p=>!all.Any(c=>c.Input.Corrects==p.Input.Id)).ToList();return new{records=all,groups=active.GroupBy(p=>PayoutGroup(p.Input)).Select(g=>{var latest=g.Last();var actual=g.Sum(p=>p.Input.Actual);var expected=CurrentPayoutExpected(latest);return new{channel=latest.Input.ChannelId,orderIds=latest.Input.OrderIds,template=latest.Input,expected,actual,difference=expected-actual,status=expected==null?"Fees incomplete":expected==actual?"Reconciled":"Unresolved difference / partial settlement"};})};}
 public PayoutRecord RecordPayout(PayoutInput input)=>SalesCommand(input.Id,"payout",input,(db,tx)=>{
  Guard.Text(input.Reference,"Payout reference",150);Guard.Require(input.OrderIds is {Count:>0 and <=1000}&&input.OrderIds.Distinct().Count()==input.OrderIds.Count,"Select distinct orders.");StockDate(input.Date);Guard.Amount(input.Actual,"Actual bank amount");Guard.Require(input.Notes.Length<=4000,"Notes too long.");Guard.Amount(input.OtherFees,"Other fees");Guard.Amount(input.Refunds,"Refunds");if(input.Commission!=null)Guard.Amount(input.Commission.Value,"Commission including fee VAT");Guard.Require(Math.Abs(input.Adjustments)<=1000000,"Adjustment too large.");if(input.Adjustments!=0)Guard.Text(input.Notes,"Explain adjustments and who owns tips, delivery charges or promotions");
  var orders=input.OrderIds.Select(id=>ReadOrder(db,tx,id)).ToList();Guard.Require(orders.All(o=>o.ChannelId==input.ChannelId&&o.Status=="completed"),"Match completed orders from this channel.");var prior=Payouts();Guard.Require(!prior.Any(p=>p.Input.ChannelId==input.ChannelId&&p.Input.Reference==input.Reference),"Payout reference already recorded.");
  var active=prior.Where(p=>!prior.Any(c=>c.Input.Corrects==p.Input.Id)).ToList();if(input.Corrects!=null){var original=active.SingleOrDefault(p=>p.Input.Id==input.Corrects)??throw new ValidationException("Choose an uncorrected payout.");Guard.Require(PayoutGroup(original.Input)==PayoutGroup(input),"A correction must retain the same matched order group.");Guard.Text(input.Notes,"Correction explanation");active.Remove(original);}
  Guard.Require(!active.Any(p=>p.Input.OrderIds.Intersect(input.OrderIds).Any()&&PayoutGroup(p.Input)!=PayoutGroup(input)),"Some orders belong to a different settlement group. Reuse the complete existing order group for partial payments, or correct that payout.");
  decimal? fees=input.Commission??TotalValue(orders.Select(o=>o.ReportedFees??o.ExpectedFees));var expected=fees==null?null:orders.Sum(o=>o.Total-o.Refunds+o.Adjustments-o.OtherFees)-fees-input.OtherFees-input.Refunds+input.Adjustments;var actual=active.Where(p=>PayoutGroup(p.Input)==PayoutGroup(input)).Sum(p=>p.Input.Actual)+input.Actual;
  var previous=active.LastOrDefault(p=>PayoutGroup(p.Input)==PayoutGroup(input));if(previous!=null&&input.Corrects==null)Guard.Require(expected==CurrentPayoutExpected(previous),"Reuse the same report totals for a partial receipt. Use a correction to change agreed fees or adjustments.");
  var p=new PayoutRecord(input,Now(),expected,expected-actual,expected==null?"Fees incomplete":expected==actual?"Reconciled":"Unresolved difference / partial settlement",orders);Execute(db,tx,"INSERT INTO sales_payouts VALUES($id,$r,$c,$b)",("$id",input.Id),("$r",input.Reference),("$c",input.ChannelId),("$b",JsonSerializer.Serialize(p,Json)));
  foreach(var o in orders){var updated=o with{Revision=o.Revision+1,PaymentStatus=p.Status=="Reconciled"?"settled":"part-settled"};WriteOrder(db,tx,updated);Execute(db,tx,"INSERT INTO sales_events VALUES($id,$o,$at,$h,$b,$r)",("$id",input.Id+":"+o.Id),("$o",o.Id),("$at",Now()),("$h",SalesHash(input)),("$b",JsonSerializer.Serialize(new{action="payout",payoutId=input.Id,reference=input.Reference},Json)),("$r",JsonSerializer.Serialize(updated,Json)));}return p;
 });
}
